 3	import java.util.Arrays;
 4	import java.util.Objects;
 5	
 6	public final class CountingSort {
 7	
 8	    private CountingSort() {
 9	        // Utility class.
10	    }
11	
12	    /**
13	     * Returns a sorted copy of the supplied values using counting sort.
14	     *
15	     * <p>The input array is never modified.</p>
16	     */
17	    public static int[] sort(int[] values) {
18	        Objects.requireNonNull(values, "values");
19	        if (values.length < 2) {
20	            return Arrays.copyOf(values, values.length);
21	        }
22	
23	        int min = values[0];
24	        int max = values[0];
25	        for (int value : values) {
26	            if (value < min) {
27	                min = value;
28	            } else if (value > max) {
29	                max = value;
30	            }
31	        }
32	
33	        int[] positions = buildPositions(values, min, max);
34	        return buildSortedCopy(values, positions, min);
35	    }
36	
37	    private static int[] buildPositions(int[] values, int min, int max) {
38	        int[] counts = buildCounts(values, min, max);
39	        for (int i = 1; i < counts.length; i++) {
40	            counts[i] += counts[i - 1];
41	        }
42	        return counts;
43	    }
44	
45	    private static int[] buildCounts(int[] values, int min, int max) {
46	        long range = (long) max - min + 1L;
47	        if (range > Integer.MAX_VALUE) {
48	            throw new IllegalArgumentException("Input range is too large for counting sort");
49	        }
50	
51	        int[] counts = new int[(int) range];
52	        for (int value : values) {
53	            counts[value - min]++;
54	        }
55	        return counts;
56	    }
57	
58	    private static int[] buildSortedCopy(int[] values, int[] positions, int min) {
59	        int[] sorted = new int[values.length];
60	        for (int i = values.length - 1; i >= 0; i--) {
61	            int value = values[i];
62	            sorted[--positions[value - min]] = value;
63	        }
64	        return sorted;
65	    }
66	}

